CREATE TABLE shipment_latest (shipment_id integer PRIMARY KEY REFERENCES shipments (id), status text NOT NULL, occurred_at timestamptz NOT NULL, event_id integer NOT NULL);

INSERT INTO shipment_latest (shipment_id, status, occurred_at, event_id)
SELECT DISTINCT ON (e.shipment_id) e.shipment_id, e.status, e.occurred_at, e.id
FROM shipment_events e
ORDER BY e.shipment_id, e.occurred_at DESC, e.id DESC
ON CONFLICT (shipment_id) DO UPDATE SET status = EXCLUDED.status, occurred_at = EXCLUDED.occurred_at, event_id = EXCLUDED.event_id;
